  "labels": [
    {
      "label": "S_Competition",
      "span": "another player challenge me to a game",
      "rule_applied": "definition",
      "rationale": "The span explicitly describes the game making players compete against one another."
    }
  ],
  "invoked_web_search": false,
  "search_query": null,
  "search_result": null
}

