  "labels": [
    {
      "label": "T_Grinding",
      "span": "you'll be doing chores in order to get to them.",
      "rule_applied": "definition",
      "rationale": "The review describes tedious tasks that must be performed to make progress toward the puzzle content."
    }
  ],
